import fs from 'node:fs';
import path from 'node:path';
import { setupAzureCliEnv } from './index';
import { getCACertificates } from '../../../utils/ca-cert';

// CA-cert resolution and the file write are stubbed so the tests assert only env-var behavior.
jest.mock('../../../utils/ca-cert');

const mockedGetCACertificates = getCACertificates as jest.MockedFunction<typeof getCACertificates>;

const ENV_KEYS = [
  'REQUESTS_CA_BUNDLE',
  'AZURE_CLI_DISABLE_CONNECTION_VERIFICATION',
  'HTTPS_PROXY',
  'HTTP_PROXY',
  'NO_PROXY'
];

const TLS_ON = {
  shouldVerifyTls: true,
  shouldUseCustomCaCertificate: false,
  shouldKeepDefaultCaCertificates: true
};

describe('setupAzureCliEnv', () => {
  const originalEnv: Record<string, string | undefined> = {};
  let writeSpy: jest.SpyInstance;
  let rmSyncSpy: jest.SpyInstance;
  let mkdtempSpy: jest.SpyInstance;

  beforeAll(() => {
    ENV_KEYS.forEach((k) => (originalEnv[k] = process.env[k]));
  });

  beforeEach(() => {
    jest.clearAllMocks();
    ENV_KEYS.forEach((k) => delete process.env[k]);
    mockedGetCACertificates.mockReturnValue({ caCertificates: null } as any);
    writeSpy = jest.spyOn(fs, 'writeFileSync').mockImplementation(() => undefined);
    rmSyncSpy = jest.spyOn(fs, 'rmSync').mockImplementation(() => undefined);
    mkdtempSpy = jest.spyOn(fs, 'mkdtempSync').mockReturnValue('/tmp/.bruno-az-test' as any);
  });

  afterEach(() => {
    writeSpy.mockRestore();
    rmSyncSpy.mockRestore();
    mkdtempSpy.mockRestore();
    ENV_KEYS.forEach((k) => delete process.env[k]);
  });

  afterAll(() => {
    ENV_KEYS.forEach((k) => {
      if (originalEnv[k] === undefined) delete process.env[k];
      else process.env[k] = originalEnv[k];
    });
  });

  const PROXY_OFF = { disabled: true };

  describe('CA bundle', () => {
    it('writes the bundle into a private mkdtemp subdir and points REQUESTS_CA_BUNDLE at it', () => {
      mockedGetCACertificates.mockReturnValue({ caCertificates: 'PEM-DATA' } as any);
      const expectedBundlePath = path.join('/tmp/.bruno-az-test', 'ca-bundle.pem');

      const restore = setupAzureCliEnv({ options: TLS_ON, appLevelProxyConfig: PROXY_OFF, caBundleDir: '/tmp' });

      expect(mkdtempSpy).toHaveBeenCalledWith(path.join('/tmp', '.bruno-az-'));
      expect(writeSpy).toHaveBeenCalledWith(expectedBundlePath, 'PEM-DATA', { mode: 0o600 });
      expect(process.env.REQUESTS_CA_BUNDLE).toBe(expectedBundlePath);

      restore();
      expect(process.env.REQUESTS_CA_BUNDLE).toBeUndefined();
      // The per-run bundle dir is removed on restore, not left on disk.
      expect(rmSyncSpy).toHaveBeenCalledWith('/tmp/.bruno-az-test', { recursive: true, force: true });
    });

    it('removes the created subdir if writing the bundle fails', () => {
      mockedGetCACertificates.mockReturnValue({ caCertificates: 'PEM-DATA' } as any);
      writeSpy.mockImplementation(() => {
        throw new Error('ENOSPC');
      });

      expect(() =>
        setupAzureCliEnv({ options: TLS_ON, appLevelProxyConfig: PROXY_OFF, caBundleDir: '/tmp' })
      ).toThrow('ENOSPC');

      // The dir created before the failed write is cleaned up, and no env var is left set.
      expect(rmSyncSpy).toHaveBeenCalledWith('/tmp/.bruno-az-test', { recursive: true, force: true });
      expect(process.env.REQUESTS_CA_BUNDLE).toBeUndefined();
    });

    it('does not create or delete a bundle dir on restore when no CA certs are present', () => {
      mockedGetCACertificates.mockReturnValue({ caCertificates: null } as any);

      const restore = setupAzureCliEnv({ options: TLS_ON, appLevelProxyConfig: PROXY_OFF, caBundleDir: '/tmp' });
      restore();

      expect(mkdtempSpy).not.toHaveBeenCalled();
      expect(rmSyncSpy).not.toHaveBeenCalled();
    });

    it('does not write or set REQUESTS_CA_BUNDLE when there are no CA certs', () => {
      mockedGetCACertificates.mockReturnValue({ caCertificates: null } as any);

      setupAzureCliEnv({ options: TLS_ON, appLevelProxyConfig: PROXY_OFF, caBundleDir: '/tmp' });

      expect(writeSpy).not.toHaveBeenCalled();
      expect(process.env.REQUESTS_CA_BUNDLE).toBeUndefined();
    });

    it('forwards the custom CA path to getCACertificates only when shouldUseCustomCaCertificate is set', () => {
      setupAzureCliEnv({
        options: {
          shouldVerifyTls: true,
          shouldUseCustomCaCertificate: true,
          customCaCertificateFilePath: '/my/ca.pem',
          shouldKeepDefaultCaCertificates: false
        },
        appLevelProxyConfig: PROXY_OFF,
        caBundleDir: '/tmp'
      });
      expect(mockedGetCACertificates).toHaveBeenCalledWith({ caCertFilePath: '/my/ca.pem', shouldKeepDefaultCerts: false });

      mockedGetCACertificates.mockClear();
      setupAzureCliEnv({
        options: { shouldVerifyTls: true, shouldUseCustomCaCertificate: false, customCaCertificateFilePath: '/my/ca.pem', shouldKeepDefaultCaCertificates: true },
        appLevelProxyConfig: PROXY_OFF,
        caBundleDir: '/tmp'
      });
      expect(mockedGetCACertificates).toHaveBeenCalledWith({ caCertFilePath: undefined, shouldKeepDefaultCerts: true });
    });
  });

  describe('TLS verification', () => {
    it('disables az CLI connection verification when TLS verification is off', () => {
      setupAzureCliEnv({
        options: { ...TLS_ON, shouldVerifyTls: false },
        appLevelProxyConfig: PROXY_OFF,
        caBundleDir: '/tmp'
      });
      expect(process.env.AZURE_CLI_DISABLE_CONNECTION_VERIFICATION).toBe('1');
    });

    it('leaves connection verification enabled when TLS verification is on', () => {
      setupAzureCliEnv({ options: TLS_ON, appLevelProxyConfig: PROXY_OFF, caBundleDir: '/tmp' });
      expect(process.env.AZURE_CLI_DISABLE_CONNECTION_VERIFICATION).toBeUndefined();
    });
  });

  describe('proxy env vars', () => {
    it('sets HTTPS_PROXY/HTTP_PROXY with URL-encoded credentials for an authenticated proxy', () => {
      setupAzureCliEnv({
        options: TLS_ON,
        appLevelProxyConfig: {
          protocol: 'http',
          hostname: 'proxy.example.com',
          port: 8080,
          auth: { disabled: false, username: 'user@x', password: 'p@ss' }
        },
        caBundleDir: '/tmp'
      });

      const expected = 'http://user%40x:p%40ss@proxy.example.com:8080';
      expect(process.env.HTTPS_PROXY).toBe(expected);
      expect(process.env.HTTP_PROXY).toBe(expected);
    });

    it('omits credentials and sets NO_PROXY from bypassProxy for an unauthenticated proxy', () => {
      setupAzureCliEnv({
        options: TLS_ON,
        appLevelProxyConfig: {
          protocol: 'http',
          hostname: 'proxy.example.com',
          port: 3128,
          auth: { disabled: true },
          bypassProxy: 'localhost,127.0.0.1'
        },
        caBundleDir: '/tmp'
      });

      expect(process.env.HTTPS_PROXY).toBe('http://proxy.example.com:3128');
      expect(process.env.HTTP_PROXY).toBe('http://proxy.example.com:3128');
      expect(process.env.NO_PROXY).toBe('localhost,127.0.0.1');
    });

    it('sets no proxy env vars when the global proxy is disabled or inherited', () => {
      setupAzureCliEnv({ options: TLS_ON, appLevelProxyConfig: { disabled: true }, caBundleDir: '/tmp' });
      expect(process.env.HTTPS_PROXY).toBeUndefined();
      expect(process.env.HTTP_PROXY).toBeUndefined();

      setupAzureCliEnv({ options: TLS_ON, appLevelProxyConfig: { inherit: true, hostname: 'ignored' }, caBundleDir: '/tmp' });
      expect(process.env.HTTPS_PROXY).toBeUndefined();
      expect(process.env.HTTP_PROXY).toBeUndefined();
    });
  });

  describe('restore', () => {
    it('restores pre-existing values and clears vars it newly set', () => {
      process.env.HTTPS_PROXY = 'http://original:1';

      const restore = setupAzureCliEnv({
        options: TLS_ON,
        appLevelProxyConfig: {
          protocol: 'http',
          hostname: 'proxy.example.com',
          port: 3128,
          auth: { disabled: true },
          bypassProxy: 'localhost'
        },
        caBundleDir: '/tmp'
      });

      expect(process.env.HTTPS_PROXY).toBe('http://proxy.example.com:3128');
      expect(process.env.NO_PROXY).toBe('localhost');

      restore();

      expect(process.env.HTTPS_PROXY).toBe('http://original:1');
      expect(process.env.HTTP_PROXY).toBeUndefined();
      expect(process.env.NO_PROXY).toBeUndefined();
    });
  });
});
